def relative_seek(stream, offset):
    stream.seek(offset, 1)
    return stream

class Seekable:
    def __init__(self, stream):
        self.stream = stream

    def seek(self, offset, whence=0):
        self.stream.seek(offset, whence)

        return self

    def relative_seek(self, offset):
        return self.seek(offset, 1)

    def read(self, size=-1):
        return self.stream.read(size)

import itertools

def combination_index(iterable, element):
    return list(itertools.combinations(iterable, len(element))).index(element)

def combination_with_replacement_index(iterable, element):
    return list(itertools.combinations_with_replacement(iterable, len(element))).index(element)

def permutation_index(iterable, element):
    return list(itertools.permutations(iterable, len(element))).index(element)

def product_index(iterable, element):
    return list(itertools.product(iterable, repeat=len(element))).index(element)

import numpy as np

def polynomial_eval(coefficients, x):
    return np.polyval(coefficients, x)

import math

def nth_combination_with_replacement(iterable, n, k):
    return list(itertools.combinations_with_replacement(iterable, k))[n]

def all_unique(iterable):
    return len(iterable) == len(set(iterable))

def nth_permutation(iterable, n):
    return list(itertools.permutations(iterable))[n]

def value_chain(iterable):
    chain = iterable[0]
    for element in iterable[1:]:
        chain = chain * element
    return chain

import itertools

def iterate(initial_value, func, stop_condition=None):
    result = initial_value
    while True:
        if stop_condition and stop_condition(result):
            break
        yield result
        result = func(result)

def partial_product(iterables):
    result = 1
    for iterable in iterables:
        result *= iterable
    return result

def gray_product(iterables):
    result = 1
    for iterable in iterables:
        result *= iterable
    return result

def unique_in_window(iterable, n):
    window = {}
    for element in iterable:
        if element not in window:
            window[element] = 1
        else:
            del window[element]
        if len(window) >= n:
            yield from window.keys()

def duplicates_everseen(iterable):
    seen = set()
    for element in iterable:
        if element in seen:
            yield element
        seen.add(element)

import numpy as np

def polynomial_derivative(coefficients):
    return np.polyder(coefficients)
